insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_eng4_v1'
from (values
('110.39.c.2.A',3,'A senior reading Beowulf in translation wants to know how an Old English word was used centuries ago. Which resource helps most?','["a historical or etymological dictionary", "a rhyming guide", "a world atlas", "a modern pocket speller"]'::jsonb,0,'Historical dictionaries trace older usage.','original'),
('110.39.c.2.A',3,'A student meets the term ''iambic pentameter'' in a critical essay. Where is the most reliable place to check its precise meaning?','["a sports almanac", "a glossary of literary terms", "a bus schedule", "a recipe book"]'::jsonb,1,'Literary glossaries define critical terms.','original'),
('110.39.c.2.B',3,'A critic calls a ruler''s speech ''regal'' while another calls it ''pompous.'' What distinguishes the two words?','["their lengths only", "their spelling histories only", "their connotations", "their rhymes"]'::jsonb,2,'Same subject, different emotional coloring.','original'),
('110.39.c.2.B',4,'In a poem, ''the sea swallowed the ship'' uses ''swallowed'' in what way?','["literally", "technically", "denotatively only", "figuratively"]'::jsonb,3,'The sea does not literally swallow.','original'),
('110.39.c.2.B',3,'Which word has the most positive connotation for a person who refuses to change a view?','["steadfast", "obstinate", "stubborn", "pigheaded"]'::jsonb,0,'The others imply rigidity.','original'),
('110.39.c.2.C',3,'A reviewer calls a performance ''tour de force.'' What does the phrase mean?','["a failed effort", "a display of great skill", "a quiet rehearsal", "a short trip"]'::jsonb,1,'French for ''feat of strength.''','original'),
('110.39.c.2.C',3,'What does ''carpe diem'' encourage?','["avoiding all risk", "waiting patiently", "making the most of the present moment", "remembering the past"]'::jsonb,2,'Latin for ''seize the day.''','original'),
('110.39.c.2.C',4,'A scholar describes a poet''s ''ennui.'' What does the French word suggest?','["fierce anger", "great joy", "sharp curiosity", "weary boredom or listlessness"]'::jsonb,3,'Ennui is deep dissatisfaction.','original'),
('110.39.c.4.F',4,'Passage: ''The castle gates stood open, though no smoke rose from a single chimney.'' What can a reader infer?','["the castle may be abandoned or in trouble", "winter has just ended happily", "the king is arriving", "a feast is under way"]'::jsonb,0,'Open gates and no smoke imply emptiness.','original'),
('110.39.c.4.F',3,'A narrator says her sister ''rehearsed her smile in the hall mirror before entering the room.'' What does this suggest?','["the sister is practicing a song", "the sister is hiding her real feelings", "the room is dark", "the sister dislikes mirrors"]'::jsonb,1,'Rehearsed expressions imply concealment.','original'),
('110.39.c.4.G',3,'When a reader evaluates details to find a key idea, what question helps most?','["which word is rarest", "which sentence is shortest", "which details repeat or build toward the same point", "which page is first"]'::jsonb,2,'Repetition signals importance.','original'),
('110.39.c.4.G',4,'An essay gives a single vivid anecdote followed by four paragraphs of data on the same theme. What is the key idea likely to be?','["the anecdote alone", "the number of paragraphs", "the title font", "the theme the data and anecdote jointly support"]'::jsonb,3,'Details converge on the main idea.','original'),
('110.39.c.4.H',4,'A student reads a parliamentary speech and a newspaper editorial about the same law. What does synthesizing them produce?','["a view of how the law was defended and received", "no new understanding", "a list of spelling errors", "a copy of the speech"]'::jsonb,0,'Combining sources yields a fuller picture.','original'),
('110.39.c.4.H',3,'Which sentence best shows synthesis across texts?','["''The treaty has articles.''", "''Together, the diary and the treaty reveal why the village feared the border.''", "''The diary is old.''", "''I read both.''"]'::jsonb,1,'Synthesis connects ideas.','original'),
('110.39.c.4.I',3,'A reader finds that Shakespearean language blurs her understanding of a scene. Which strategy helps most?','["skipping the speeches", "reading faster", "paraphrasing each speech into modern language", "reading only stage directions"]'::jsonb,2,'Paraphrasing improves comprehension.','original'),
('110.39.c.4.I',3,'Which question helps a reader monitor comprehension while reading a dense critical essay?','["''What color is the cover?''", "''How many words are on a page?''", "''Who printed this?''", "''Can I restate the author''s argument in my own words?''"]'::jsonb,3,'Self-checking guides adjustment.','original'),
('110.39.c.5.B',4,'A student compares how two Romantic poets treat nature, one reverent and one fearful. What does the comparison require?','["evidence from both poems about each attitude", "a quotation from only one poem", "a biography of each poet only", "a rhyme count"]'::jsonb,0,'Cross-text comparison needs evidence.','original'),
('110.39.c.5.B',3,'A strong written comparison of two plays should include what?','["a list of actors", "specific similarities and differences supported with evidence", "plot summary only", "a single adjective"]'::jsonb,1,'Comparisons need evidence.','original'),
('110.39.c.5.C',3,'An interpretive paragraph quotes a soliloquy and then argues what it reveals about the speaker''s doubt. The argument that follows the quotation is what?','["a footnote", "a bibliography entry", "original commentary", "a stage direction"]'::jsonb,2,'Commentary interprets the evidence.','original'),
('110.39.c.5.C',4,'Which choice is strongest interpretive writing about a quoted line?','["''The line has a word.''", "''Page 4.''", "''This is a quote.''", "''The repeated word \"darkness\" suggests the speaker''s despair is growing.''"]'::jsonb,3,'Interpretation explains meaning.','original'),
('110.39.c.5.D',3,'A faithful paraphrase of ''The queen''s silence was louder than any decree'' would be:','["The queen''s refusal to speak carried more force than an official order.", "The queen was not present.", "The decree was silent.", "The queen shouted a decree."]'::jsonb,0,'A paraphrase preserves meaning.','original'),
('110.39.c.5.D',3,'A summary of a complicated argument should do what?','["add the summarizer''s opinion", "state the central claim and key supports briefly", "copy every sentence", "skip the claim"]'::jsonb,1,'Summaries are concise and faithful.','original'),
('110.39.c.5.F',3,'Which word is the most precise academic term for ''a main idea running through a literary work''?','["scene", "noise", "theme", "mood only"]'::jsonb,2,'Themes are central ideas.','original'),
('110.39.c.5.F',3,'In an essay on Parliament, which word names a formal vote to approve a law?','["dessert", "costume", "rumor", "ratification"]'::jsonb,3,'Content-area vocabulary aids precision.','original'),
('110.39.c.5.G',4,'''The manor''s portraits stared down on a table set for guests who never came.'' What implicit meaning is suggested?','["loneliness and the passing of better days", "the portraits are valuable", "the cook is late", "a party is about to start"]'::jsonb,0,'Details imply a mood of loss.','original'),
('110.39.c.5.G',3,'An explicit meaning is found where?','["only in the title page", "in what the text directly says", "only between the lines", "only in the reader''s mind"]'::jsonb,1,'Explicit meaning is stated.','original'),
('110.39.c.5.J',4,'A critic says a poem is ''meaningless'' but cites no lines. What is the best challenge?','["poems are always meaningless", "the poem is too short", "the claim lacks supporting evidence from the text", "critics are always wrong"]'::jsonb,2,'A claim needs textual support.','original'),
('110.39.c.5.J',3,'A reader wants to defend an author''s view that technology isolates people. What should the reader do?','["summarize the cover", "list the author''s other books", "state a personal opinion only", "cite passages that show characters becoming isolated"]'::jsonb,3,'Defend with text evidence.','original'),
('110.39.c.6.A',4,'Two British novels portray characters trapped by class expectations. How can their themes be compared?','["by examining how each plot and character shows the limits of class", "by comparing the covers", "by ignoring the endings", "by comparing the number of chapters"]'::jsonb,0,'Compare how themes develop.','original'),
('110.39.c.6.A',3,'A king who cannot rule himself brings his kingdom to ruin. Which theme does this plot develop?','["kingdoms are safe", "self-control is needed for leadership", "rulers need no discipline", "ruin is accidental"]'::jsonb,1,'Characterization and plot show theme.','original'),
('110.39.c.6.B',3,'A tragic hero is often defined by what?','["a lack of conflict", "perfect virtue", "a flaw that contributes to his downfall", "an unchanging fortune"]'::jsonb,2,'The tragic flaw drives downfall.','original'),
('110.39.c.6.B',4,'A character who appears villainous but reveals a painful past becomes believable through what?','["flat traits", "silence", "repetition of one trait", "complexity and context"]'::jsonb,3,'Complex motives add believability.','original'),
('110.39.c.6.C',3,'A short scene in which servants whisper about a coming betrayal contributes what to the plot?','["foreshadowing of conflict", "the epigraph", "a rhyme scheme", "the denouement"]'::jsonb,0,'Isolated scenes can set up later events.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'English Language Arts and Reading' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_eng4_v1'
from (values
('110.39.c.6.C',4,'A play''s final scene reunites estranged family members. How does it contribute to the whole?','["it is unrelated", "it resolves central conflicts and reinforces theme", "it changes the genre", "it introduces a new conflict"]'::jsonb,1,'Closing scenes complete the structure.','original'),
('110.39.c.6.D',3,'A novel set in Victorian England shows a child laborer in a factory. How does this historical setting influence the story?','["it makes the plot comic", "it hides the character", "it shapes the character''s hardships and the social critique", "it removes conflict"]'::jsonb,2,'Historical context shapes events and theme.','original'),
('110.39.c.6.D',4,'A medieval tale in which a knight must prove his honor reflects what about its culture?','["modern attitudes only", "a rhyme scheme", "no cultural values", "the era''s values of chivalry and reputation"]'::jsonb,3,'Cultural setting shapes characters.','original'),
('110.39.c.7.A',3,'Who wrote ''The Canterbury Tales''?','["Geoffrey Chaucer", "John Milton", "Jane Austen", "Charles Dickens"]'::jsonb,0,'A medieval frame story in verse.','original'),
('110.39.c.7.A',3,'Which Shakespeare tragedy centers on a Danish prince who seeks to avenge his father?','["Macbeth", "Hamlet", "King Lear", "Othello"]'::jsonb,1,'Hamlet is the prince of Denmark.','original'),
('110.39.c.7.A',3,'Which author wrote the Victorian novel ''Great Expectations''?','["George Eliot", "Thomas Hardy", "Charles Dickens", "Oscar Wilde"]'::jsonb,2,'A coming-of-age novel.','original'),
('110.39.c.7.A',4,'Which poet wrote the epic ''Paradise Lost''?','["Lord Byron", "William Blake", "Samuel Coleridge", "John Milton"]'::jsonb,3,'A seventeenth-century epic in blank verse.','original'),
('110.39.c.7.A',3,'Which novel by Mary Shelley explores the consequences of creating life?','["Frankenstein", "Wuthering Heights", "Dracula", "Jane Eyre"]'::jsonb,0,'A founding Gothic and science-fiction novel.','original'),
('110.39.c.7.B',3,'A Shakespearean sonnet ends with what structure?','["a haiku", "a rhyming couplet", "a free-verse stanza", "an unrhymed line"]'::jsonb,1,'The final two lines rhyme.','original'),
('110.39.c.7.B',4,'Blank verse is written in what form?','["haiku", "rhymed couplets", "unrhymed iambic pentameter", "free verse"]'::jsonb,2,'Used in many Shakespeare plays.','original'),
('110.39.c.7.B',3,'A line of iambic pentameter contains how many metrical feet?','["ten", "seven", "three", "five"]'::jsonb,3,'Penta means five.','original'),
('110.39.c.7.C',3,'A comic character in a tragedy provides momentary relief from tension. This convention is called what?','["comic relief", "an epigraph", "an index", "a soliloquy"]'::jsonb,0,'Comic relief lightens tone.','original'),
('110.39.c.7.C',4,'In a play, a character reveals a secret plan while alone onstage. This is a feature of what?','["a stage curtain", "a soliloquy", "an epilogue", "a prologue"]'::jsonb,1,'Soliloquies reveal private thoughts.','original'),
('110.39.c.7.D.i',3,'Which sentence is the best thesis for an essay on a novel''s use of setting?','["''I will discuss setting.''", "''Settings are places.''", "''The novel''s foggy moors mirror the heroine''s confusion and isolation.''", "''The novel has moors.''"]'::jsonb,2,'A thesis states a specific, arguable claim.','original'),
('110.39.c.7.D.i',4,'A strong concluding paragraph in an analytical essay typically does what?','["lists new questions only", "introduces an unrelated claim", "repeats the introduction exactly", "synthesizes the argument and explains its significance"]'::jsonb,3,'Conclusions emphasize significance.','original'),
('110.39.c.7.D.ii',3,'An essay argues that a play''s tone grows darker in each act. Which organization best matches this thesis?','["an act-by-act progression", "a list of characters", "alphabetical order", "random order"]'::jsonb,0,'Structure mirrors the thesis.','original'),
('110.39.c.7.E.i',3,'Which claim is most arguable?','["''Libraries have books.''", "''Public libraries should be funded before stadiums.''", "''Funding is money.''", "''Stadiums are large.''"]'::jsonb,1,'Arguable claims can be debated.','original'),
('110.39.c.7.E.i',3,'An appeal to shared values and beliefs is mostly an appeal to what?','["logos only", "syntax", "ethos", "meter"]'::jsonb,2,'Ethos builds trust and shared identity.','original'),
('110.39.c.7.E.ii',4,'A writer says, ''While some argue the tax burdens small shops, it also funds the roads those shops depend on.'' This is an example of what?','["a title", "an anecdote", "a summary", "addressing a counterargument"]'::jsonb,3,'The writer answers an opposing view.','original'),
('110.39.c.7.E.ii',3,'Which type of evidence is a historical example?','["an event from the past used to support a point", "an opinion with no source", "a rumor", "a slogan"]'::jsonb,0,'Examples illustrate claims.','original'),
('110.39.c.7.E.iii',3,'A writer adjusts vocabulary and examples to suit readers with limited background knowledge. This shows awareness of what?','["meter", "audience", "rhyme", "plot"]'::jsonb,1,'Audience shapes choices.','original'),
('110.39.c.7.F',3,'A news website pairs an article with an interactive timeline. What does the interactive element allow?','["silent reading only", "the article to disappear", "readers to explore events at their own pace", "the author to change the facts"]'::jsonb,2,'Interactive features engage users.','original'),
('110.39.c.7.F',3,'A podcast adapts a classic novel. Which feature distinguishes it as a multimodal text?','["page numbers", "margins", "chapter titles only", "sound effects and voice acting"]'::jsonb,3,'Audio adds a mode.','original'),
('110.39.c.8.A',3,'An article reports facts about a historic battle without taking sides. What is the author''s purpose?','["to inform", "to command", "to persuade", "to amuse"]'::jsonb,0,'Neutral reporting informs.','original'),
('110.39.c.8.A',4,'A satirical essay proposes an outrageous remedy to expose a social failing. What is the underlying purpose?','["to give instructions", "to criticize through irony", "to advertise", "to entertain with no point"]'::jsonb,1,'Satire criticizes.','original'),
('110.39.c.8.A',3,'A speech delivered to graduating seniors offers advice and encouragement. Who is the intended audience?','["no one", "toddlers", "the graduates", "scientists only"]'::jsonb,2,'Audience is signaled by occasion.','original'),
('110.39.c.8.B',3,'A historical essay describes how rising bread prices led to riots and then to reform. What structure is this?','["classification", "spatial", "alphabetical", "cause and effect"]'::jsonb,3,'Events link in chains.','original'),
('110.39.c.8.B',3,'A text lists categories of poetry and describes each in turn. What structure is this?','["classification", "compare and contrast", "problem and solution", "chronological"]'::jsonb,0,'Items are grouped by type.','original'),
('110.39.c.8.C',3,'Why might a reference book include a footnote?','["to hide the author", "to give a source or additional note without interrupting the main text", "to decorate the page", "to replace the chapter"]'::jsonb,1,'Footnotes supplement.','original'),
('110.39.c.8.C',4,'A line graph in an economics article best shows what?','["a poem''s meter", "a map route", "trends over time", "parts of a whole"]'::jsonb,2,'Line graphs track change.','original'),
('110.39.c.8.D',4,'An author calls the king''s court ''a glittering cage.'' How does this language shape perception?','["it has no meaning", "it suggests the court is shabby", "it suggests freedom", "it suggests luxury that confines people"]'::jsonb,3,'Metaphor shapes views.','original'),
('110.39.c.8.D',3,'An author repeatedly uses ''toil'' instead of ''work'' to describe labor. What does the choice suggest?','["that the labor is hard and burdensome", "that the labor is easy", "that the labor is brief", "that the labor is fun"]'::jsonb,0,'Diction affects perception.','original'),
('110.39.c.8.E',3,'A character says ''How thoughtful'' after being insulted. This is an example of what?','["foreshadowing", "sarcasm", "a motif", "a flashback"]'::jsonb,1,'The words mean the opposite.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'English Language Arts and Reading' and d.language = 'en'
on conflict (fingerprint) do nothing;
