select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_eng4_v1'
from (values
('110.39.c.8.E',4,'A repeated image of blood throughout a tragedy is an example of what?','["an epigraph", "a stage direction", "a motif", "a pun"]'::jsonb,2,'Motifs recur with meaning.','original'),
('110.39.c.8.E',3,'A thief steals a policeman''s wallet in front of the police station. What kind of irony is this?','["sarcasm", "verbal irony", "dramatic irony", "situational irony"]'::jsonb,3,'The outcome is unexpected.','original'),
('110.39.c.8.F',3,'Elevated, formal diction in a narrator''s account of a coronation creates what effect?','["a solemn, ceremonial tone", "a bitter tone", "a casual tone", "a playful tone"]'::jsonb,0,'Diction shapes tone.','original'),
('110.39.c.8.F',4,'Short, fragmented sentences in a character''s panicked monologue create what effect?','["a calm, measured pace", "a sense of urgency and distress", "a stately pace", "a dreamy mood"]'::jsonb,1,'Syntax shapes mood.','original'),
('110.39.c.8.F',3,'A narrator''s voice is dry, witty and understated. Which element most contributes to this voice?','["the font", "the cover", "diction and sentence rhythm", "page numbers"]'::jsonb,2,'Voice emerges from language choices.','original'),
('110.39.c.8.G',3,'''To be, or not to be'' sets up a contrast that is an example of what?','["alliteration", "onomatopoeia", "hyperbole", "antithesis"]'::jsonb,3,'Opposites are juxtaposed.','original'),
('110.39.c.8.G',3,'A speaker repeats a similar sentence structure across several sentences to build momentum. This is called what?','["parallelism", "understatement", "irony", "antithesis"]'::jsonb,0,'Parallel structure builds rhythm.','original'),
('110.39.c.8.G',4,'A speech moves from criticism of a policy to a proposal for reform. What does this rhetorical shift accomplish?','["it repeats the opening", "it moves the audience from problem to solution", "it avoids the topic", "it ends the speech abruptly"]'::jsonb,1,'Shifts structure persuasion.','original'),
('110.39.c.9.B.i',3,'Which organizational pattern best suits an essay arguing that a policy should change?','["alphabetical order", "random order", "claim, evidence, counterargument, conclusion", "a list of rhymes"]'::jsonb,2,'Arguments follow a logical structure.','original'),
('110.39.c.9.B.ii',3,'Which supports the claim that a character is ambitious?','["he lives in a town", "he owns a coat", "he eats breakfast", "he rehearses speeches nightly and courts powerful allies"]'::jsonb,3,'Specific details develop ideas.','original'),
('110.39.c.9.B.ii',4,'Depth of thought in a body paragraph is shown by what?','["explaining the significance of the evidence", "using longer sentences", "repeating the topic sentence", "adding more quotations without comment"]'::jsonb,0,'Commentary shows insight.','original'),
('110.39.c.9.C',3,'A writer deletes a repeated sentence and tightens wordy phrases. What is being improved?','["margins", "clarity and concision", "spelling only", "typeface"]'::jsonb,1,'Revision tightens style.','original'),
('110.39.c.9.C',3,'Replacing ''big'' with ''monumental'' improves what?','["punctuation", "paragraph breaks", "diction", "capitalization"]'::jsonb,2,'More precise words improve style.','original'),
('110.39.c.9.D',3,'Which sentence uses the correct pronoun?','["Each of the actors forgot our lines.", "Each of the actors forgot their lines happily.", "Each of the actors forgot its lines.", "Each of the actors forgot his or her lines."]'::jsonb,3,'A singular antecedent takes a singular pronoun in formal usage.','original'),
('110.39.c.9.D',3,'In ''the thames flows through london,'' which words need capital letters?','["the, thames and london", "thames only", "london only", "flows and through"]'::jsonb,0,'Capitalize the first word and the names of places.','original'),
('110.39.c.9.D',3,'Which sentence has a spelling error?','["The senate approved the budget.", "The queen''s reign was marked by prosperity and sucess.", "The queen''s reign was marked by prosperity and success.", "The audience applauded loudly."]'::jsonb,1,'''Success'' has a double c and double s.','original'),
('110.39.c.10.D',3,'Which element is needed in a professional cover letter?','["slang expressions", "emoji", "a clear statement of the position sought", "a joke opening"]'::jsonb,2,'Professional correspondence states its purpose.','original'),
('110.39.c.10.D',3,'Which greeting is appropriate when the recipient''s name is unknown?','["Yo,", "Hi friend,", "Hey there,", "To Whom It May Concern:"]'::jsonb,3,'A neutral formal greeting.','original'),
('110.39.c.11.E',3,'A student researching the Industrial Revolution wants a primary source. Which is best?','["a worker''s letter written in 1840", "a textbook paragraph", "a modern blog summary", "a documentary review"]'::jsonb,0,'Primary sources come from the era.','original'),
('110.39.c.11.F',3,'When a researcher synthesizes information, the final product should do what?','["copy one source", "blend ideas from sources into a new, organized understanding", "list sources only", "avoid citing"]'::jsonb,1,'Synthesis builds a coherent whole.','original'),
('110.39.c.11.H',3,'Which of the following is plagiarism?','["summarizing and citing", "quoting a sentence with a citation", "using another writer''s exact paragraph without credit", "paraphrasing and citing"]'::jsonb,2,'Uncredited copying is plagiarism.','original'),
('110.39.c.11.G.i',3,'An article about a medicine is written by the company that sells it. What should a careful reader consider?','["that the article is perfectly objective", "that sellers never exaggerate", "that all claims are proven", "the possibility of bias"]'::jsonb,3,'Conflicts of interest can skew content.','original'),
('110.39.c.11.G.i',4,'A source describes only one side of a debate and omits all counterevidence. This indicates what?','["possible bias by omission", "balanced coverage", "strong credibility", "peer review"]'::jsonb,0,'Omission skews perspective.','original'),
('110.39.c.11.G.ii',3,'''No one has proven ghosts do not exist, so they must be real'' is an example of what?','["expert testimony", "faulty reasoning from lack of proof", "statistical evidence", "sound deduction"]'::jsonb,1,'Absence of disproof is not proof.','original'),
('110.39.c.11.G.ii',3,'''Either you support this bill, or you hate your country'' is an example of what?','["an anecdote", "a statistic", "an either-or fallacy", "a balanced argument"]'::jsonb,2,'It limits options falsely.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'English Language Arts and Reading' and d.language = 'en'
on conflict (fingerprint) do nothing;
